ENTRIES.append(dict(module='naming', title='81数理详解（十六）：第46-48数——沉舟、结果与立鹤', content='第46数（载宝沉舟）凶：满载沉没之数，象征虽有收获但终将失去。代表财来财去、难以守成。此数出现在总格时主晚年破财，出现在地格时主家庭财产损失。起名时应以守财吉数化解，如第24、15等。第47数（开花结果）吉：开花结实之数，象征努力终有回报、事业有成。代表性格踏实、肯吃苦，终获成功。此数出现在人格时主中年事业稳固，出现在总格时主晚年硕果累累。男女皆宜。第48数（青松立鹤）吉：青松白鹤之数，象征品格高洁、长寿安康。代表性格淡泊名利、健康长寿。此数出现在总格时主晚年健康幸福，出现在人格时主一生清贵。适合学者、艺术家。', category='起名', keywords='81数理,第46数,第47数,第48数,载宝沉舟,开花结果,青松立鹤,吉,凶'))
ENTRIES.append(dict(module='naming', title='81数理详解（十七）：第49-51数——难分、参半与盛衰', content='第49数（吉凶难分）凶：转变不定之数，象征命运变化莫测、吉凶难料。代表一生多转折，好坏参半。此数出现在人格时主中年运势不定，出现在总格时主晚年变化无常。起名时宜以大吉之数稳定命局。第50数（吉凶参半）凶：一成一败之数，象征成功与失败交替出现。代表事业多有起伏，难以长久保持。此数出现在总格时主晚年财运不稳。起名时应以稳固吉数化解，如第31、16等。第51数（一盛一衰）半吉：盛衰交替之数，象征命运起伏但总体尚可。代表一生有盛有衰，但能东山再起。此数为半吉，需看与其他格位的配合。若配合大吉之数，可转凶为吉。', category='起名', keywords='81数理,第49数,第50数,第51数,吉凶难分,吉凶参半,一盛一衰,凶,半吉'))
ENTRIES.append(dict(module='naming', title='81数理详解（十八）：第52-54数——星空、困苦与悲运', content='第52数（眼望星空）大吉：先见之明之数，象征目光远大、洞察力强。代表才智过人、有先见之明，适合投资、研究等领域。此数出现在人格时主中年事业有成，出现在总格时主晚年名利双收。男女皆宜。第53数（忧愁困苦）凶：忧心如焚之数，象征一生忧愁不断、困难重重。代表内心常感不安、事业多阻碍。此数出现在人格时主中年运势低迷，出现在地格时主家庭不宁。起名时应以吉数化解。第54数（多难悲运）凶：辛苦多难之数，象征一生辛苦劳累、多灾多难。代表事业难成、健康堪忧。此数出现在总格时主晚年凄惨。起名时务必以大吉之数替代，不可轻视。', category='起名', keywords='81数理,第52数,第53数,第54数,眼望星空,忧愁困苦,多难悲运,大吉,凶'))
ENTRIES.append(dict(module='naming', title='81数理详解（十九）：第55-57数——外苦、行舟与青松', content='第55数（外美内苦）凶：外表光鲜内心痛苦之数，象征表面风光但内心忧虑。代表外在成功但内在不安，常有隐忧。此数出现在人格时主中年外强中干，出现在总格时主晚年虽有积蓄但身心不宁。起名时宜以内心安定之吉数化解。第56数（浪里行舟）凶：浪中行舟之数，象征一生颠簸不定、难以安稳。代表事业多波折、居无定所。此数出现在地格时主家庭搬迁频繁，出现在总格时主晚年漂泊。起名时应以稳固吉数化解。第57数（寒雪青松）吉：雪中青松之数，象征经霜不凋、坚韧不拔。代表虽然经历困难但终能屹立不倒。此数出现在人格时主中年虽难但稳，出现在总格时主晚年德高望重。', category='起名', keywords='81数理,第55数,第56数,第57数,外美内苦,浪里行舟,寒雪青松,吉,凶'))
ENTRIES.append(dict(module='naming', title='81数理详解（二十）：第58-60数——遇雨、悲风与夺利', content='第58数（晚行遇雨）半吉：晚景多变之数，象征晚年虽有波折但终有转机。代表中年辛苦、晚年渐入佳境。此数为半吉，需配合其他吉数方为全吉。出现在总格时主晚年先苦后甜。第59数（寒蝉悲风）凶：寒风凛冽之数，象征事业处处受阻、困难重重。代表虽有才能但时运不济，常感怀才不遇。此数出现在人格时主中年事业多败，出现在总格时主晚年凄凉。起名时务必避开。第60数（争名夺利）凶：无谋之争之数，象征争名夺利但终无所获。代表好争好斗但缺乏谋略，常因争斗而失败。此数出现在外格时主人际关系紧张。起名时应以温和吉数化解。', category='起名', keywords='81数理,第58数,第59数,第60数,晚行遇雨,寒蝉悲风,争名夺利,半吉,凶'))
ENTRIES.append(dict(module='naming', title='81数理详解（二十一）：第61-63数——芙蓉、孤独与化育', content='第61数（牡丹芙蓉）吉：名利双收之数，象征才华出众、名利兼得。代表品格高雅、受人爱戴，一生事业顺遂。此数出现在人格时主中年名望双全，出现在总格时主晚年荣华富贵。男女皆宜，尤利文艺工作者。第62数（衰败孤独）凶：衰败孤寂之数，象征事业衰败、孤独终老。代表意志消沉、缺乏进取心。此数出现在人格时主中年事业走下坡，出现在总格时主晚年孤独凄凉。起名时务必以大吉之数替代。第63数（万物化育）吉：天地化育之数，象征生机勃勃、万物繁荣。代表才干出众、事业兴旺。此数出现在人格时主中年事业蒸蒸日上，出现在总格时主晚年家业兴旺。为起名优选吉数。', category='起名', keywords='81数理,第61数,第62数,第63数,牡丹芙蓉,衰败孤独,万物化育,吉,凶'))
ENTRIES.append(dict(module='naming', title='81数理详解（二十二）：第64-65数——分离与长寿', content='第64数（骨肉分离）凶：骨肉离散之数，象征家庭破裂、亲人分离。代表家庭关系紧张、亲缘淡薄。此数出现在地格时主家庭不睦、夫妻分离，出现在总格时主晚年子女不孝、孤苦无依。起名时必须以家庭和睦之吉数化解，如第15、24、31等大吉之数。第65数（富贵长寿）大吉：富贵双全之数，象征大富大贵、健康长寿。代表一生金运旺盛、福寿绵长。此数为八十一数理中最佳吉数之一，适用于任何格位。出现在人格时主中年事业辉煌，出现在总格时主晚年福寿双全。男女皆宜，尤利经商者。', category='起名', keywords='81数理,第64数,第65数,骨肉分离,富贵长寿,大吉,凶'))
ENTRIES.append(dict(module='naming', title='81数理详解（二十三）：第66-67数——暗淡与长久', content='第66数（逻辑暗淡）凶：暗淡无光之数，象征前途暗淡、事业无光。代表才能平庸、缺乏机遇。此数出现在人格时主中年事业平庸，出现在总格时主晚年黯淡无光。起名时应以光明吉数化解，如第13、21、33等。第67数（路途长久）吉：路途通达之数，象征事业长久稳健、持续发展。代表性格踏实、做事有恒心，能长久坚持。此数出现在人格时主中年事业稳步上升，出现在总格时主晚年基业长青。适合从事需要长期积累的行业，如学术、医疗、教育等。男女皆宜。', category='起名', keywords='81数理,第66数,第67数,逻辑暗淡,路途长久,吉,凶'))
ENTRIES.append(dict(module='naming', title='81数理详解（二十四）：第68-69数——兴顾与非运', content='第68数（兴顾四方）吉：兴旺四方之数，象征事业兴旺、声名远播。代表才干卓越、广结善缘，事业版图广阔。此数出现在人格时主中年事业蒸蒸日上，出现在外格时主人脉广泛。适合从事商业、外交等需要广泛社交的工作。男女皆宜。第69数（非业非运）凶：非业非运之数，象征事业不成、命运多舛。代表一生多灾多难、事业难成，常处困境。此数出现在人格时主中年事业多败，出现在总格时主晚年穷困潦倒。起名时务必以大吉之数替代，不可等闲视之。若命局必现，宜用第15、24、31等大吉数补救。', category='起名', keywords='81数理,第68数,第69数,兴顾四方,非业非运,吉,凶'))
ENTRIES.append(dict(module='naming', title='81数理详解（二十五）：第70-71数——悲愁与劳神', content='第70数（凄惨悲愁）凶：凄惨寂寥之数，象征一生凄惨、悲愁不断。代表事业失败、家庭破裂、健康堪忧。此数为八十一数理中较凶之数，出现在总格时主晚年极为凄凉。起名时绝对不可使用，必须以大吉之数替代。第71数（损力劳神）半吉：劳心劳力之数，象征辛苦劳累但收获有限。代表做事费力不讨好，常感疲惫。此数为半吉半凶，需看与其他格位的配合。若配合大吉之数，可减轻辛劳；若配合凶数，则更加劳累。出现在外格时主人际关系辛苦，出现在地格时主家庭操劳。', category='起名', keywords='81数理,第70数,第71数,凄惨悲愁,损力劳神,半吉,凶'))
ENTRIES.append(dict(module='naming', title='81数理详解（二十六）：第72-73数——先甘后苦与志高力微', content='第72数（先甘后苦）凶：先甜后苦之数，象征早年顺利但晚年凄凉。代表少年得志但中年开始走下坡，晚景凄惨。此数出现在总格时主晚年破败。起名时应以晚年安稳之吉数化解，如第15、24、31等。尤需注意总格不可落入此数。第73数（志高力微）半吉：志大才疏之数，象征志向远大但能力不足。代表好高骛远、眼高手低，常因目标过高而失败。此数为半吉，需配合实际能力。若人格与地格配合大吉之数，可增强执行力；若配合凶数，则更加力不从心。出现在人格时需注意培养实际能力。', category='起名', keywords='81数理,第72数,第73数,先甘后苦,志高力微,半吉,凶'))
ENTRIES.append(dict(module='naming', title='81数理详解（二十七）：第74-75数——经霜与保全', content='第74数（残菊经霜）凶：残菊遭霜之数，象征事业衰退、晚景凄凉。代表曾经辉煌但终归失败，如秋菊经霜。此数出现在总格时主晚年败落，出现在人格时主中年运势急转直下。起名时务必避开，以大吉之数替代。第75数（退可保全）吉：退守保全之数，象征退一步海阔天空、以退为进。代表虽然不宜进取但能守住已有成果。此数出现在人格时主中年以退为进、稳守基业，出现在总格时主晚年安稳。适合性格沉稳、不喜争斗之人。此数虽非大吉，但胜在安稳，适合保守型命局。', category='起名', keywords='81数理,第74数,第75数,残菊经霜,退可保全,吉,凶'))
ENTRIES.append(dict(module='naming', title='81数理详解（二十八）：第76-77数——破家与先苦后甘', content='第76数（离祖破家）凶：离乡背井之数，象征离祖别乡、家业破败。代表与家庭关系紧张、早年离家发展。此数出现在地格时主家庭不睦、早年离家，出现在总格时主晚年家业难保。起名时应以家庭和睦之吉数化解。第77数（先苦后甘）半吉：先苦后甜之数，象征早年辛苦但晚年幸福。代表少年时期多磨炼，中年后逐渐好转。此数为半吉，需看与其他格位的配合。若人格与地格配合大吉之数，可缩短辛苦期；若配合凶数，则辛苦期延长。出现在总格时主晚年终获安宁。适合白手起家之人。', category='起名', keywords='81数理,第76数,第77数,离祖破家,先苦后甘,半吉,凶'))
ENTRIES.append(dict(module='naming', title='81数理详解（二十九）：第78-79数——凄凉与乏力', content='第78数（晚景凄凉）凶：晚景萧条之数，象征晚年孤独凄凉、无人照料。代表中年虽有事业但晚年破败。此数出现在总格时主晚年极为凄惨，出现在地格时主家庭晚年不睦。起名时务必避开总格落入此数，应以晚年安泰之吉数替代，如第15、24、31等大吉之数。第79数（挽回乏力）凶：回天无力之数，象征虽然努力挽回但终归失败。代表事业走下坡时无力回天。此数出现在人格时主中年事业难以挽回，出现在总格时主晚年无力改变困境。起名时务必以大吉之数替代，不可存侥幸心理。', category='起名', keywords='81数理,第78数,第79数,晚景凄凉,挽回乏力,凶'))
ENTRIES.append(dict(module='naming', title='81数理详解（三十）：第80-81数——最凶与归本', content='第80数（最凶之数）凶：凶中最凶之数，象征万事归空、一事无成。代表一生多灾多难、家破人亡。此数为八十一数理中最凶之数，起名时绝对不可使用。若命局不幸落入此数，必须以多个大吉之数全力补救，如第15、24、31、33等。建议重新选字以避开此数。第81数（还元归本）大吉：万物回归之数，象征返璞归真、功成名就。代表一生经历丰富、终得圆满。此数出现在总格时主晚年功成身退、安享天年，出现在人格时主大器晚成。为八十一数理的收官之数，寓意善始善终、功德圆满。男女皆宜，尤利晚年安泰。', category='起名', keywords='81数理,第80数,第81数,最凶之数,还元归本,大吉,凶'))
ENTRIES.append(dict(module='naming', title='生肖起名用字表（一）：鼠年（子鼠）起名宜忌', content='鼠为十二生肖之首，地支属子，五行属水。鼠年起名宜用字：①"米""禾""豆""麦"等粮食类字，象征粮食丰盛、衣食无忧；②"口""宀""广"等洞穴类字，象征有安身之所、家业稳固；③"王""君""大"等尊贵字，因子鼠为十二生肖之首，有称王之意；④"夕""夜"等夜间字，因鼠为夜行动物，象征得其时也。鼠年起名忌用字：①"马""午"等字，因子午相冲，为大忌；②"羊""未"等字，因子未相害；③"日""光"等字，因鼠畏日光，象征不得其时；④"人""亻"等字，因鼠怕人，象征受人欺压。推荐用字举例：秀、秉、秦、宇、宏、琼、珍、君、夜、夕等。', category='起名', keywords='生肖起名,鼠年,子鼠,宜用字,忌用字,粮食,洞穴,子午冲,子未害'))
ENTRIES.append(dict(module='naming', title='生肖起名用字表（二）：牛年（丑牛）起名宜忌', content='牛为十二生肖第二，地支属丑，五行属土。牛年起名宜用字：①"氵""水""冫"等水旁字，因牛需饮水，水生万物，象征资源丰沛（但注意丑牛本身属土，水土不宜过多）；②"艹""禾""豆""麦"等植物类字，象征粮食充足、劳有所获；③"宀""冖"等洞穴类字，象征有遮蔽休息之所；④"田""力"等字，因牛耕田，象征勤劳有功。牛年起名忌用字：①"羊""未"等字，因丑未相冲；②"马""午"等字，因丑午相害；③"心""忄"等字，因牛为素食动物，见肉则不安；④"日"字过多，因牛在烈日下劳作辛苦。推荐用字举例：茂、芊、苗、蕾、宁、宜、田、力、勤、朴等。', category='起名', keywords='生肖起名,牛年,丑牛,宜用字,忌用字,植物,田力,丑未冲,丑午害'))
ENTRIES.append(dict(module='naming', title='生肖起名用字表（三）：虎年（寅虎）起名宜忌', content='虎为十二生肖第三，地支属寅，五行属木。虎年起名宜用字：①"山""林""木"等山林类字，因虎为山林之王，象征得其地势；②"王""君""大"等王者字，虎为百兽之王，象征威权；③"水""氵"等水旁字，因水生木，虎得水则旺；④"月""夕"等字，因虎为夜行猛兽，月下更显威风。虎年起名忌用字：①"猴""申"等字，因寅申相冲；②"蛇""巳"等字，因寅巳相害；③"门""关"等字，因虎被困则失威；④"小""少"等字，因虎不可小，小则失威。推荐用字举例：山、峰、林、森、木、桐、王、瑞、珊、湖、月、朗等。', category='起名', keywords='生肖起名,虎年,寅虎,宜用字,忌用字,山林,王者,寅申冲,寅巳害'))
ENTRIES.append(dict(module='naming', title='生肖起名用字表（四）：兔年（卯兔）起名宜忌', content='兔为十二生肖第四，地支属卯，五行属木。兔年起名宜用字：①"艹""禾""米""豆"等粮食类字，因兔为草食动物，象征食物充足；②"宀""冖""穴"等洞穴类字，因兔居洞穴，象征有安身之所；③"月"字及月相关字，因传说月中有玉兔，象征高贵祥瑞；④"木""林"等木旁字，因卯属木，木助木旺。兔年起名忌用字：①"鸡""酉"等字，因卯酉相冲；②"龙""辰"等字，因卯辰相害；③"日"字，因日与月相对，兔性属阴，不宜日字；④"鹰""猎"等字，因鹰猎克兔，象征受威胁。推荐用字举例：芊、蓉、茗、安、宜、月、朗、朋、林、彬等。', category='起名', keywords='生肖起名,兔年,卯兔,宜用字,忌用字,粮食,洞穴,月,卯酉冲,卯辰害'))
ENTRIES.append(dict(module='naming', title='生肖起名用字表（五）：龙年（辰龙）起名宜忌', content='龙为十二生肖第五，地支属辰，五行属土。龙年起名宜用字：①"水""氵""雨"等水类字，因龙得水则飞腾，象征事业腾达；②"日""月""星"等天体字，因龙行天上，象征尊贵；③"王""君""帝"等王者字，龙为帝王象征，代表至高无上；④"金""钅"等金字，因辰龙含金气，金水相生。龙年起名忌用字：①"狗""戌"等字，因辰戌相冲；②"兔""卯"等字，因辰卯相害；③"虫""蛇"等字，有降格之意；④"小""少"等字，龙不可小。推荐用字举例：浩、海、雨、星、晨、王、瑜、瑞、金、铭、龙、辰等。', category='起名', keywords='生肖起名,龙年,辰龙,宜用字,忌用字,水雨,王者,天体,辰戌冲,辰卯害'))
ENTRIES.append(dict(module='naming', title='生肖起名用字表（六）：蛇年（巳蛇）起名宜忌', content='蛇为十二生肖第六，地支属巳，五行属火。蛇年起名宜用字：①"口""宀""冖"等洞穴类字，因蛇居洞穴，象征有安身之所；②"木""艹"等木旁字，因蛇喜草丛，象征得其环境；③"田""土"等字，因蛇在田间活动，象征自然自在；④"衣""彡""巾"等字，因蛇蜕皮如换衣，象征蜕变新生。蛇年起名忌用字：①"猪""亥"等字，因巳亥相冲；②"虎""寅"等字，因寅巳相害；③"水""氵"过多之字，因水克火，对巳蛇不利；④"日"字过多，因蛇畏烈日。推荐用字举例：宇、安、容、蓉、芝、芳、田、域、衣、彦、彤等。', category='起名', keywords='生肖起名,蛇年,巳蛇,宜用字,忌用字,洞穴,草木,巳亥冲,寅巳害'))
ENTRIES.append(dict(module='naming', title='生肖起名用字表（七）：马年（午马）起名宜忌', content='马为十二生肖第七，地支属午，五行属火。马年起名宜用字：①"艹""禾""豆""麦"等粮食类字，象征粮食充足、精力充沛；②"木""林"等木旁字，因木生火，助午马之旺；③"人""亻"等字，因马为人之良伴，象征得人缘；④"衣""彡""巾"等字，象征披挂整齐、英姿飒爽。马年起名忌用字：①"鼠""子"等字，因子午相冲；②"牛""丑"等字，因丑午相害；③"水""氵"过多之字，因水克火；④"田"字，因马在田中劳作辛苦，不如自由奔腾。推荐用字举例：荣、茂、秉、林、彬、杰、俊、伟、裕、彤、彦等。', category='起名', keywords='生肖起名,马年,午马,宜用字,忌用字,粮食,木,子午冲,丑午害'))
ENTRIES.append(dict(module='naming', title='生肖起名用字表（八）：羊年（未羊）起名宜忌', content='羊为十二生肖第八，地支属未，五行属土。羊年起名宜用字：①"艹""禾""豆""米"等粮食类字，因羊为草食动物，象征食物丰足；②"木""林"等木旁字，因未为木库，木助其旺；③"人""亻"等字，因羊性温顺，与人亲近，象征人缘好；④"月"字，因羊与月相关，象征温柔祥和。羊年起名忌用字：①"牛""丑"等字，因丑未相冲；②"鼠""子"等字，因子未相害；③"犬""犭"等字，因犬克羊；④"刀""刂"等字，因刀宰羊，象征受伤害。推荐用字举例：茂、芊、蓉、茉、萱、杰、俊、伦、月、朋、祥等。', category='起名', keywords='生肖起名,羊年,未羊,宜用字,忌用字,粮食,木,丑未冲,子未害'))
ENTRIES.append(dict(module='naming', title='生肖起名用字表（九）：猴年（申猴）起名宜忌', content='猴为十二生肖第九，地支属申，五行属金。猴年起名宜用字：①"木""林""艹"等木旁字，因猴居林间，象征得其环境；②"人""亻"等字，因猴与人类相近，象征聪明灵巧；③"口""宀"等字，象征有安身之所；④"王""大"等字，因猴称美猴王，象征尊贵。猴年起名忌用字：①"虎""寅"等字，因寅申相冲；②"猪""亥"等字，因申亥相害；③"火""灬"等火旁字过多，因火克金；④"鸟""隹"等字，因鸟猴相争。推荐用字举例：林、森、桐、彬、俊、杰、宇、安、瑞、瑜、铭等。', category='起名', keywords='生肖起名,猴年,申猴,宜用字,忌用字,木,人,寅申冲,申亥害'))
ENTRIES.append(dict(module='naming', title='生肖起名用字表（十）：鸡年（酉鸡）起名宜忌', content='鸡为十二生肖第十，地支属酉，五行属金。鸡年起名宜用字：①"米""禾""豆""麦"等粮食类字，因鸡食五谷，象征粮食丰足；②"金""钅"等金字，因酉属金，金助其旺；③"山""石"等字，因鸡栖息于山石之上，象征得其地势；④"鸟""隹"等字，因鸡为禽类，象征同类相聚。鸡年起名忌用字：①"兔""卯"等字，因卯酉相冲；②"狗""戌"等字，因酉戌相害；③"火""灬"过多之字，因火克金；④"刀""刂"等字，因刀宰鸡。推荐用字举例：秀、秉、秦、金、铭、钰、山、磊、鹏、雅、维等。', category='起名', keywords='生肖起名,鸡年,酉鸡,宜用字,忌用字,粮食,金,卯酉冲,酉戌害'))
ENTRIES.append(dict(module='naming', title='生肖起名用字表（十一）：狗年（戌狗）起名宜忌', content='狗为十二生肖第十一，地支属戌，五行属土。狗年起名宜用字：①"人""亻"等字，因狗为人之忠实伙伴，象征忠诚守信；②"肉""月"等字，因狗食肉，象征食物充足（注意"月"旁也有肉月旁之意）；③"宀""冖"等字，象征有家可归、忠诚护主；④"小"字，因小狗可爱，象征讨人喜欢。狗年起名忌用字：①"龙""辰"等字，因辰戌相冲；②"鸡""酉"等字，因酉戌相害；③"田"字，因狗在田中为野狗，不如家犬；④"两口"字型（如"吕""哭"等），有哭丧之意。推荐用字举例：俊、伟、伦、仁、忠、信、安、宜、小、少等。', category='起名', keywords='生肖起名,狗年,戌狗,宜用字,忌用字,人,肉,辰戌冲,酉戌害'))
ENTRIES.append(dict(module='naming', title='生肖起名用字表（十二）：猪年（亥猪）起名宜忌', content='猪为十二生肖第十二，地支属亥，五行属水。猪年起名宜用字：①"艹""禾""豆""米"等粮食类字，因猪食五谷，象征粮食丰盛、生活富足；②"宀""冖"等洞穴类字，象征有安身之所、家庭温暖；③"金""钅"等金字，因金生水，助亥猪之旺；④"人""亻"等字，因猪与人类关系密切，象征被人珍爱。猪年起名忌用字：①"蛇""巳"等字，因巳亥相冲；②"猴""申"等字，因申亥相害；③"刀""刂""力"等字，因刀宰猪，象征受伤害；④"水""氵"过多之字，因亥猪本身属水，水过多则泛滥。推荐用字举例：茂、芊、蓉、安、宜、铭、钰、俊、杰、家等。', category='起名', keywords='生肖起名,猪年,亥猪,宜用字,忌用字,粮食,洞穴,巳亥冲,申亥害'))
ENTRIES.append(dict(module='naming', title='五行偏旁用字分类（一）：金属性用字', content='五行属金的偏旁主要包括金、钅、辛、酉等。金属性字代表刚毅、果断、锐利，适合五行缺金或喜金之人使用。金属性常用起名字（20+字）：金、铭、钰、锐、锋、铮、银、锦、镇、钊、钏、钐、铃、铄、鉴、鑫、辛、辞、酉、醇、醒、酥、鎏、钘、钰、锘、钟、钢、铠、锡、铸。金属性字在起名中的运用原则：①金主义，代表正义、义气，适合性格需要增强决断力的人；②金生水，若命局水弱，可用金字生水；③金克木，若命局木过旺，可用金字克制；④金旺之人不宜过多使用金字，以免过刚则折。典型金属性好名举例：铭远、钰涵、锐志、锦程、铮然、鑫宇等。金属性字与秋季、西方、白色相应，出生在秋季或命局喜金者尤宜。', category='起名', keywords='五行,金属性,偏旁,金,钅,辛,酉,起名用字,金生水,金克木'))
ENTRIES.append(dict(module='naming', title='五行偏旁用字分类（二）：木属性用字', content='五行属木的偏旁主要包括木、艹、竹等。木属性字代表生机、成长、仁慈，适合五行缺木或喜木之人使用。木属性常用起名字（20+字）：木、林、森、桐、柏、松、柳、杨、枫、栋、梁、彬、梓、楠、楚、荣、茂、芳、芷、芝、蕾、蓉、茉、萱、葵、苑、英、华、萌、竹、笙。木属性字在起名中的运用原则：①木主仁，代表仁慈、善良，适合性格需要增强温和度的人；②木生火，若命局火弱，可用木字生火；③木克土，若命局土过旺，可用木字克制；④木旺之人不宜过多使用木字，以免过柔则弱。典型木属性好名举例：梓涵、彬然、森宇、桐华、荣轩、芳宁等。木属性字与春季、东方、青绿色相应，出生在春季或命局喜木者尤宜。', category='起名', keywords='五行,木属性,偏旁,木,艹,竹,起名用字,木生火,木克土'))
ENTRIES.append(dict(module='naming', title='五行偏旁用字分类（三）：水属性用字', content='五行属水的偏旁主要包括水、氵、雨等。水属性字代表智慧、柔韧、灵动，适合五行缺水或喜水之人使用。水属性常用起名字（20+字）：水、永、泉、泰、浩、海、波、涛、润、泽、洁、清、源、汇、洋、涵、湖、湘、潮、沐、雨、雪、露、霖、霏、霁、雷、霜、淼、渝、淳。水属性字在起名中的运用原则：①水主智，代表智慧、聪明，适合需要增强思维能力的人；②水生木，若命局木弱，可用水字生木；③水克火，若命局火过旺，可用水字克制；④水旺之人不宜过多使用水字，以免过柔则散。典型水属性好名举例：浩然、泽宇、涵清、润泽、永泉、海宁等。水属性字与冬季、北方、黑色相应，出生在冬季或命局喜水者尤宜。', category='起名', keywords='五行,水属性,偏旁,水,氵,雨,起名用字,水生木,水克火'))
ENTRIES.append(dict(module='naming', title='五行偏旁用字分类（四）：火属性用字', content='五行属火的偏旁主要包括火、灬、日等。火属性字代表热情、光明、礼仪，适合五行缺火或喜火之人使用。火属性常用起名字（20+字）：火、炎、焱、灿、焕、烨、煜、炜、烁、炫、烽、焰、煦、熙、燃、灬、然、杰、熙、煮、日、明、旭、晨、星、晖、昭、晗、晔、晓、晧。火属性字在起名中的运用原则：①火主礼，代表礼仪、热情，适合需要增强社交能力的人；②火生土，若命局土弱，可用火字生土；③火克金，若命局金过旺，可用火字克制；④火旺之人不宜过多使用火字，以免过燥则躁。典型火属性好名举例：灿然、烨华、煜城、明轩、旭东、星宇等。火属性字与夏季、南方、红色相应，出生在夏季或命局喜火者尤宜。', category='起名', keywords='五行,火属性,偏旁,火,灬,日,起名用字,火生土,火克金'))
ENTRIES.append(dict(module='naming', title='五行偏旁用字分类（五）：土属性用字', content='五行属土的偏旁主要包括土、山、石等。土属性字代表厚重、稳健、诚信，适合五行缺土或喜土之人使用。土属性常用起名字（20+字）：土、地、坤、城、坚、培、基、堂、墨、壁、壤、垄、垣、垒、山、峰、岳、岚、岩、岭、崇、嵩、巍、石、磊、硕、磬、砚、碧、磊、磻。土属性字在起名中的运用原则：①土主信，代表诚信、稳重，适合需要增强可靠性的人；②土生金，若命局金弱，可用土字生金；③土克水，若命局水过旺，可用土字克制；④土旺之人不宜过多使用土字，以免过重则滞。典型土属性好名举例：坤宇、峰华、岳然、城远、墨涵、磊石等。土属性字与四季之交、中央、黄色相应，命局喜土者尤宜。', category='起名', keywords='五行,土属性,偏旁,土,山,石,起名用字,土生金,土克水'))
ENTRIES.append(dict(module='naming', title='男女起名差异与禁忌', content='男女起名在用字、音韵、数理上均有显著差异，需遵循传统姓名学原则。男性起名原则：①用字宜阳刚有力，如"伟""杰""峰""铭"等；②数理宜选刚毅吉数，如第7数（刚毅果断）、第11数（稳健吉顺）、第21数（明月光照）等；③避免过于柔弱的字，如"弱""柔""娇"等；④避免女性化偏旁，如"女"旁过多。女性起名原则：①用字宜温柔优美，如"雅""涵""萱""蕾"等；②数理宜选温和吉数，如第5数（福禄长寿）、第15数（福寿双全）、第24数（家门余庆）等；③避免过于刚强的数理，如第21数虽大吉但女性用需谨慎，恐婚姻不顺；④可用女性化偏旁如"女""彡"等。共同禁忌：①避免谐音不雅的字；②避免生僻字影响日常使用；③避免与长辈同名；④避免过于张扬的字，如"霸""天"等。', category='起名', keywords='男女起名,差异,禁忌,男性,女性,数理,用字,阳刚,温柔'))
ENTRIES.append(dict(module='naming', title='双胞胎起名技巧', content='双胞胎起名讲究关联性与区分度的平衡，既体现手足之情又彰显个性。技巧一：拆词法。将一个美好的词语拆为两个字，分别用于两个孩子。如"明哲"拆为"明"与"哲"，"锦绣"拆为"锦"与"绣"。技巧二：对仗法。用对仗工整的两个词组起名，如"云开"与"月朗"，"山高"与"水长"。技巧三：同偏旁法。使用相同偏旁但不同字形，如"森"与"林"（同木旁），"海"与"洋"（同水旁）。技巧四：同音不同字法。如同音"yu"，分别用"宇"与"语"；同音"han"，分别用"涵"与"瀚"。技巧五：数理配合法。双胞胎的五格数理应相近但不完全相同，以体现各自独立命运。注意事项：①名字不可过于相似导致难以区分；②避免一字吉一字凶的不对称情况；③考虑出生先后顺序，长幼有别；④龙凤胎（男女双胞胎）需分别遵循男女起名原则。', category='起名', keywords='双胞胎起名,拆词法,对仗法,同偏旁法,同音不同字,数理配合,龙凤胎'))
ENTRIES.append(dict(module='naming', title='改名注意事项与流程', content='改名是人生大事，需慎重对待。改名原因：①原名数理不佳，运势不顺；②谐音不雅，受人嘲笑；③名字生僻，日常不便；④人生重大转折，希望重新开始。改名流程：第一步，分析原名问题。通过五格剖象法分析原名的天格、人格、地格、外格、总格，找出不利的数理。第二步，确定改名方向。根据生辰八字确定喜用神，选择对应五行的用字。第三步，选字配数。新名字的各格数理均需吉数，尤其人格和总格必须为大吉。第四步，多方验证。检查谐音、字义、字形、与姓氏的配合度。第五步，正式使用。改名后需在日常生活中逐步使用新名，可在社交圈先行推广。注意事项：①改名不等于改命，还需自身努力配合；②新名需保留原名的优点，不可完全否定；③改名后应有一段适应期，不可急于求成；④法律改名需到户籍部门办理，民间使用可直接以新名自称；⑤改名后可在名片、社交媒体等处更新，增强新名的能量场。', category='起名', keywords='改名,注意事项,流程,五格剖象法,数理,喜用神,谐音,字义,法律改名'))

